#include <cstdio>
#include <cstdlib>
#include "tests/unit/character_motion_directional_fixture.hpp"
namespace {using namespace gf;unsigned checks=0;void check(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"mode6 frozen players: %s\n",why);std::abort();}}
bool same_players(const CharacterMotionSnapshot& a,const CharacterMotionSnapshot& b){const auto x=a.trace(),y=b.trace();if(x.size()!=y.size())return false;for(unsigned i=0;i<x.size();++i){if(x[i].has_aobj!=y[i].has_aobj||x[i].first_play!=y[i].first_play||x[i].stopped!=y[i].stopped||x[i].frame!=y[i].frame||x[i].tracks.size()!=y[i].tracks.size())return false;for(unsigned j=0;j<x[i].tracks.size();++j){const auto& p=x[i].tracks[j];const auto& q=y[i].tracks[j];if(p.channel!=q.channel||p.state!=q.state||p.flags!=q.flags||p.op!=q.op||p.interpolation!=q.interpolation||p.cursor!=q.cursor||p.time!=q.time||p.value!=q.value||p.callbacks!=q.callbacks)return false;}}return true;}}
int main(){using namespace gf;character_motion_directional_fixture::Fixture f;std::string error;check(f.load(&error),"owned fixture");CharacterMotionDriver driver;check(driver.load_directional_transitions({f.model.data(),f.model.size()},f.rig,f.profile,f.clips,f.initial,{0,-1},&error),"native library");CharacterProgramMotion initial;check(driver.select(0,f.profile.descriptors[0],false,{},1.5f,1,&initial),"old displayed ordinary pose");std::shared_ptr<const CharacterDirectionalMotionSnapshot> a,b;check(driver.request_directional_transition(0,character_motion_directional_fixture::controls,8192,5,.25f,.5f,3,initial,{4,5},{4,5},&a),"initial mode6 side/centre requests");check(a->primary().frame==.25f&&a->side().frame==.25f&&a->blend_time()==.5f,"requested target frame and clocks");
    check(driver.advance_directional_transition(a,character_motion_directional_fixture::controls,8192,5,.75f,a->models(),&b)&&b->primary().frame==.25f&&b->side().frame==.25f&&b->blend_time()==1.25f,"blend clock advances while both target frames stay frozen");
    check(same_players(*driver.snapshot(a->primary()),*driver.snapshot(b->primary()))&&same_players(*driver.snapshot(a->side()),*driver.snapshot(b->side())),"flags0 copies do NOT advance FObj/AObj/callback state");
    const f32 target=50.25f,weight=1-1.25f/4;check(std::abs(b->local_pose().bones[0].translation[0]-(target*(1-weight)+1.5f*weight))<.00001f,"temporal blend changes against a frozen directional target");a=b;
    check(driver.advance_directional_transition(a,character_motion_directional_fixture::controls,-8192,5,.25f,a->models(),&b)&&b->side_rebound()&&b->side().frame==.25f&&b->primary().frame==.25f&&same_players(*driver.snapshot(a->primary()),*driver.snapshot(b->primary())),"changed side re-requests PRIOR primary frame; centre player still frozen");
    check(driver.snapshot(b->side())->sample().bones[0].value[5]==200.25f,"side request samples new descriptor without fake time advance");a=b;
    check(driver.advance_directional_transition(a,character_motion_directional_fixture::controls,-8192,5,.75f,a->models(),&b)&&same_players(*driver.snapshot(a->primary()),*driver.snapshot(b->primary()))&&same_players(*driver.snapshot(a->side()),*driver.snapshot(b->side())),"retained opposite side freezes again");a=b;
    check(driver.advance_directional_transition(a,character_motion_directional_fixture::controls,-8192,5,2,a->models(),&b)&&!b->blending()&&b->primary().frame==.5f&&b->side().frame==.5f,"completion re-requests held frame plus overshoot only, not elapsed blend duration");
    check(b->primary().finished==0&&!driver.snapshot(b->primary())->blending(),"request sampled before source2F clear; completion not forged");a=b;
    check(driver.advance_directional_transition(a,character_motion_directional_fixture::controls,-8192,5,.5f,a->models(),&b)&&b->primary().frame==1&&b->side().frame==1&&!same_players(*driver.snapshot(a->primary()),*driver.snapshot(b->primary())),"ordinary follow resumes player advance on NEXT callback");
    auto retained=b;check(driver.interrupt_directional_transition(retained,character_motion_directional_fixture::controls,0,5,.125f,.25f,2,retained->models(),&a)&&driver.advance_directional_transition(a,character_motion_directional_fixture::controls,0,5,.25f,a->models(),&b)&&same_players(*driver.snapshot(a->primary()),*driver.snapshot(b->primary())),"interruptions retain same frozen-target rule without history chains");
    std::printf("source mode6 retained-target freeze: %u checks PASS; root/actor admission unchanged\n",checks);return 0;
}
